// Most real sites serve a sitemap index rather than a flat sitemap, so the
// first fetch usually returns a list of other sitemaps. Detect that and hand
// back one child to fetch instead of giving up.
const xml = String($json.data || '');
const locs = Array.from(xml.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/gi)).map(function (m) { return m[1].trim(); });

if (!locs.length) {
  return [{ json: { needChild: false, urls: [], note: 'No URLs found in the sitemap. Check the sitemap path in the Settings tab.' } }];
}

if (/<sitemapindex/i.test(xml)) {
  // Prefer a page sitemap over image, video or news sitemaps.
  const child = locs.find(function (u) { return !/image|video|news|category|tag|author/i.test(u); }) || locs[0];
  return [{ json: { needChild: true, childSitemap: child, urls: [] } }];
}

return [{ json: { needChild: false, urls: locs } }];

// Rather than asking the user to type a prompt list, derive the questions from
// the pages the business actually sells on. A URL path says a lot about intent,
// so pages are scored on their path and the top few win.
let urls = Array.isArray($json.urls) ? $json.urls : [];
if (!urls.length && $json.data) {
  urls = Array.from(String($json.data).matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/gi)).map(function (m) { return m[1].trim(); });
}

const settings = $('Read Brand Settings').first().json;
const wanted = Math.max(3, Math.min(12, Number(settings['Pages To Sample'] || 8) || 8));

const GOOD = [
  [/\/(pricing|plans|cost)\b/i, 40],
  [/\/(services?|solutions?|products?)\b/i, 30],
  [/\/(compare|vs|alternatives?)\b/i, 35],
  [/\/(best|top|guide|how-to)\b/i, 20],
  [/\/(use-cases?|industries|for-)\b/i, 25],
  [/\/(features?|platform|software)\b/i, 20],
  [/\/(case-stud|customers?|reviews?)\b/i, 15],
];
const BAD = /\/(tag|category|author|page\/\d|wp-|feed|privacy|terms|cookie|login|cart|checkout|\d{4}\/\d{2})\b|\.(pdf|jpg|png|xml)$/i;

const scored = [];
for (const u of urls) {
  if (BAD.test(u)) continue;
  const path = u.replace(/^https?:\/\/[^/]+/i, '') || '/';
  let score = 0;
  for (const [re, pts] of GOOD) if (re.test(path)) score += pts;
  // Shallow pages are usually the commercial ones.
  const depth = (path.match(/\//g) || []).length;
  score += Math.max(0, 12 - depth * 3);
  if (path === '/' ) score += 10;
  if (score <= 0) continue;
  scored.push({ url: u, path: path, score: score });
}

scored.sort(function (a, b) { return b.score - a.score; });
const picked = scored.slice(0, wanted);

if (!picked.length) {
  throw new Error('No commercial pages could be identified from the sitemap. Add a sitemap path that lists real pages, or lower Pages To Sample.');
}

return [{
  json: {
    brand: settings['Brand Name'],
    domain: String(settings['Domain'] || '').replace(/^https?:\/\//i, '').replace(/\/$/, ''),
    competitors: String(settings['Competitors'] || '').split(',').map(function (s) { return s.trim(); }).filter(Boolean),
    market: settings['Market'] || 'general',
    repeats: Math.max(1, Math.min(5, Number(settings['Repeats Per Question'] || 3) || 3)),
    pages: picked,
    pageList: picked.map(function (p) { return p.path; }).join('\n'),
  },
}];

