// An LLM answer is not deterministic. Asking once tells you almost nothing, so
// every question is asked several times and only the pattern across runs is
// reported later.
const brief = $('Pick Commercial Pages').first().json;
const out = $json.output || {};
const questions = Array.isArray(out.questions) ? out.questions : [];

if (!questions.length) {
  throw new Error('The question writer returned no questions. Open that node and check the model response.');
}

const items = [];
questions.forEach(function (q, qi) {
  for (let run = 1; run <= brief.repeats; run += 1) {
    items.push({
      json: {
        questionId: 'q' + (qi + 1),
        question: String(q.question || '').trim(),
        intent: String(q.intent || 'general'),
        run: run,
        brand: brief.brand,
        domain: brief.domain,
        competitors: brief.competitors,
        askedAt: new Date().toISOString(),
      },
    });
  }
});

return items;

// Perplexity and the OpenAI responses API return different shapes. Both are
// read here so everything downstream sees one record per answer: the text, the
// URLs the answer actually cited, and who was named.
function hostOf(u) {
  try { return new URL(u).hostname.replace(/^www\./i, '').toLowerCase(); } catch (e) { return ''; }
}

const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const ctx = j.questionId ? j : ($('Expand To Repeat Runs').all()[out.length] || { json: {} }).json;

  let engine = 'unknown';
  let text = '';
  let cited = [];

  // Perplexity chat completions
  if (j.choices && j.choices[0] && j.choices[0].message) {
    engine = 'Perplexity';
    text = String(j.choices[0].message.content || '');
    const list = j.citations || j.search_results || [];
    cited = list.map(function (c) { return typeof c === 'string' ? c : (c && c.url) || ''; }).filter(Boolean);
  }

  // OpenAI responses API with the web search tool
  if (Array.isArray(j.output)) {
    engine = 'ChatGPT';
    for (const block of j.output) {
      for (const c of (block.content || [])) {
        if (c.text) text += c.text;
        for (const a of (c.annotations || [])) {
          if (a.url) cited.push(a.url);
        }
      }
    }
  }

  if (!text && j.error) {
    out.push({ json: Object.assign({}, ctx, { engine: engine, failed: true, text: '', citedHosts: [], citedUrls: [], brandMentioned: false, competitorsFound: [] }) });
    continue;
  }

  const lower = text.toLowerCase();
  const brand = String(ctx.brand || '').toLowerCase();
  const domain = String(ctx.domain || '').toLowerCase();

  const citedUrls = Array.from(new Set(cited));
  const citedHosts = Array.from(new Set(citedUrls.map(hostOf).filter(Boolean)));

  const brandNamed = brand ? lower.indexOf(brand) !== -1 : false;
  const domainCited = domain ? citedHosts.some(function (h) { return h === domain || h.endsWith('.' + domain); }) : false;

  const competitorsFound = (ctx.competitors || []).filter(function (c) {
    return c && lower.indexOf(String(c).toLowerCase()) !== -1;
  });

  out.push({
    json: Object.assign({}, ctx, {
      engine: engine,
      failed: false,
      text: text.slice(0, 4000),
      citedUrls: citedUrls,
      citedHosts: citedHosts,
      brandMentioned: brandNamed,
      domainCited: domainCited,
      // Named in the prose but not linked is a weaker result than being cited.
      strength: domainCited ? 'cited' : (brandNamed ? 'named only' : 'absent'),
      competitorsFound: competitorsFound,
    }),
  });
}

return out;

// One answer is a sample, not a measurement. Group the repeats back together
// and report how consistently the brand showed up, so a single lucky mention
// is not read as visibility.
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return !r.failed; });

if (!rows.length) {
  throw new Error('Every engine call failed. Check the Perplexity and OpenAI credentials.');
}

const byQuestion = {};
rows.forEach(function (r) {
  const key = r.questionId + '|' + r.engine;
  if (!byQuestion[key]) byQuestion[key] = { questionId: r.questionId, question: r.question, intent: r.intent, engine: r.engine, runs: [] };
  byQuestion[key].runs.push(r);
});

const competitorHits = {};
let totalRuns = 0, citedRuns = 0, namedRuns = 0;

const results = Object.keys(byQuestion).map(function (k) {
  const g = byQuestion[k];
  const n = g.runs.length;
  const cited = g.runs.filter(function (r) { return r.domainCited; }).length;
  const named = g.runs.filter(function (r) { return r.brandMentioned; }).length;

  totalRuns += n; citedRuns += cited; namedRuns += named;

  g.runs.forEach(function (r) {
    (r.competitorsFound || []).forEach(function (c) { competitorHits[c] = (competitorHits[c] || 0) + 1; });
  });

  const rate = named / n;
  let stability = 'never';
  if (rate >= 0.99) stability = 'always';
  else if (rate >= 0.5) stability = 'usually';
  else if (rate > 0) stability = 'sometimes';

  return {
    questionId: g.questionId,
    question: g.question,
    intent: g.intent,
    engine: g.engine,
    runs: n,
    namedIn: named,
    citedIn: cited,
    mentionRate: Math.round(rate * 100),
    stability: stability,
  };
});

results.sort(function (a, b) { return a.mentionRate - b.mentionRate || a.questionId.localeCompare(b.questionId); });

// Share of voice counts the brand against the competitors named in the same answers.
const brandMentions = namedRuns;
const competitorTotal = Object.keys(competitorHits).reduce(function (s, k) { return s + competitorHits[k]; }, 0);
const sov = (brandMentions + competitorTotal) > 0
  ? Math.round(brandMentions / (brandMentions + competitorTotal) * 100)
  : 0;

return [{
  json: {
    brand: rows[0].brand,
    domain: rows[0].domain,
    totalRuns: totalRuns,
    citationRate: Math.round(citedRuns / totalRuns * 100),
    mentionRate: Math.round(namedRuns / totalRuns * 100),
    shareOfVoice: sov,
    competitorHits: competitorHits,
    results: results,
    blindSpots: results.filter(function (r) { return r.mentionRate === 0; }).map(function (r) { return r.question; }),
  },
}];

// This is the part that turns a score into a job list. Every URL the answers
// actually cited is collected, the brand's own pages are removed, and what is
// left is the content that is winning the citations instead.
const summary = $json;
const answers = $('Read Mentions And Citations').all().map(function (i) { return i.json; });
const domain = String(summary.domain || '').toLowerCase();

function hostOf(u) {
  try { return new URL(u).hostname.replace(/^www\./i, '').toLowerCase(); } catch (e) { return ''; }
}

const tally = {};
answers.forEach(function (a) {
  (a.citedUrls || []).forEach(function (u) {
    const h = hostOf(u);
    if (!h) return;
    if (domain && (h === domain || h.endsWith('.' + domain))) return;
    if (!tally[u]) tally[u] = { url: u, host: h, times: 0, questions: new Set(), engines: new Set() };
    tally[u].times += 1;
    tally[u].questions.add(a.questionId);
    tally[u].engines.add(a.engine);
  });
});

const ranked = Object.keys(tally).map(function (u) {
  const t = tally[u];
  return {
    url: t.url,
    host: t.host,
    timesCited: t.times,
    questionsWon: t.questions.size,
    engines: Array.from(t.engines).join(', '),
  };
}).sort(function (a, b) { return b.questionsWon - a.questionsWon || b.timesCited - a.timesCited; });

const top = ranked.slice(0, 10);

// Keep the branch alive even when nothing was cited, so the report still sends.
if (!top.length) {
  return [{ json: { placeholder: true, url: '', host: '', timesCited: 0, questionsWon: 0, engines: '' } }];
}

return top.map(function (r) { return { json: Object.assign({ placeholder: false }, r) }; });

