// Assemble the week's picture: how visible the brand was, how stable that was,
// and the specific pages and formats that took the citations instead.
const summary = $('Score Stability And Share Of Voice').first().json;
const ranked = $('Rank Cited Pages You Do Not Own').all()
  .map(function (i) { return i.json; })
  .filter(function (r) { return !r.placeholder; });

const classified = $('Classify Page Format').all().map(function (i) { return i.json.output || {}; });

const byUrl = {};
classified.forEach(function (c) { if (c && c.sourceUrl) byUrl[c.sourceUrl] = c; });

const gaps = ranked.map(function (r, i) {
  const c = byUrl[r.url] || classified[i] || {};
  return {
    url: r.url,
    host: r.host,
    questionsWon: r.questionsWon,
    timesCited: r.timesCited,
    engines: r.engines,
    pageFormat: c.pageFormat || 'unknown',
    topic: c.topic || '',
    whyItWins: c.whyItWins || '',
  };
});

// Which formats are taking the citations, so the brief writes itself.
const formatCount = {};
gaps.forEach(function (g) { formatCount[g.pageFormat] = (formatCount[g.pageFormat] || 0) + 1; });
const formatRank = Object.keys(formatCount)
  .map(function (k) { return { format: k, count: formatCount[k] }; })
  .sort(function (a, b) { return b.count - a.count; });

// Week over week, read from whatever the history tab last held for this brand.
const prevRows = $('Read Previous Week').all().map(function (i) { return i.json; })
  .filter(function (r) { return r && r['Brand'] === summary.brand && r['Mention Rate'] !== undefined; });
const prev = prevRows.length ? prevRows[prevRows.length - 1] : null;
const prevRate = prev ? Number(prev['Mention Rate']) : null;
const delta = prevRate === null || isNaN(prevRate) ? null : summary.mentionRate - prevRate;

const competitorList = Object.keys(summary.competitorHits || {})
  .map(function (k) { return { name: k, mentions: summary.competitorHits[k] }; })
  .sort(function (a, b) { return b.mentions - a.mentions; });

function esc(s) {
  return String(s === undefined || s === null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const rowsHtml = gaps.map(function (g) {
  return '<tr><td><a href="' + esc(g.url) + '">' + esc(g.host) + '</a></td><td>' + esc(g.pageFormat) +
    '</td><td>' + esc(g.topic) + '</td><td align="right">' + g.questionsWon + '</td></tr>';
}).join('');

const blindHtml = (summary.blindSpots || []).slice(0, 8)
  .map(function (q) { return '<li>' + esc(q) + '</li>'; }).join('');

const html =
  '<h2>AI citation gap report for ' + esc(summary.brand) + '</h2>' +
  '<p>Across ' + summary.totalRuns + ' answers from ChatGPT and Perplexity this week, ' + esc(summary.brand) +
  ' was named in ' + summary.mentionRate + '% and cited by link in ' + summary.citationRate + '%.' +
  (delta === null ? '' : ' That is ' + (delta >= 0 ? 'up ' : 'down ') + Math.abs(delta) + ' points on last week.') +
  ' Share of voice against the tracked competitors is ' + summary.shareOfVoice + '%.</p>' +
  (competitorList.length ? '<p>Most named competitors: ' + competitorList.slice(0, 5).map(function (c) {
    return esc(c.name) + ' (' + c.mentions + ')'; }).join(', ') + '.</p>' : '') +
  (formatRank.length ? '<p>The citations are going mostly to ' + formatRank.slice(0, 3).map(function (f) {
    return esc(f.format) + ' pages'; }).join(', ') + '.</p>' : '') +
  '<h3>Pages taking the citations</h3>' +
  '<table border="1" cellpadding="6" cellspacing="0"><tr><th>Source</th><th>Format</th><th>Topic</th><th>Questions won</th></tr>' +
  (rowsHtml || '<tr><td colspan="4">No external pages were cited this run.</td></tr>') + '</table>' +
  (blindHtml ? '<h3>Questions where the brand never appeared</h3><ul>' + blindHtml + '</ul>' : '');

return [{
  json: {
    brand: summary.brand,
    domain: summary.domain,
    runDate: new Date().toISOString().slice(0, 10),
    totalRuns: summary.totalRuns,
    mentionRate: summary.mentionRate,
    citationRate: summary.citationRate,
    shareOfVoice: summary.shareOfVoice,
    deltaVsLastWeek: delta,
    dropped: delta !== null && delta <= -10,
    topCompetitor: competitorList.length ? competitorList[0].name : '',
    formatRank: formatRank,
    blindSpots: summary.blindSpots || [],
    gaps: gaps,
    reportHtml: html,
    slackText: '*AI citation gap, ' + summary.brand + '*\nNamed in ' + summary.mentionRate +
      '% of answers, cited in ' + summary.citationRate + '%, share of voice ' + summary.shareOfVoice + '%.' +
      (delta === null ? '' : ' Change on last week: ' + (delta >= 0 ? '+' : '') + delta + ' points.') +
      (formatRank.length ? '\nCitations are going to ' + formatRank[0].format + ' pages most often.' : '') +
      (gaps.length ? '\nTop gap: ' + gaps[0].host + ' (' + gaps[0].pageFormat + ') won ' + gaps[0].questionsWon + ' questions.' : ''),
  },
}];

// One row per gap, so the sheet reads like a content backlog a writer can pick
// up rather than a blob inside a report.
const r = $json;
const out = [];

(r.gaps || []).forEach(function (g, i) {
  out.push({
    json: {
      gapId: r.brand + ' | ' + r.runDate + ' | ' + (i + 1),
      runDate: r.runDate,
      brand: r.brand,
      rank: i + 1,
      sourceUrl: g.url,
      sourceHost: g.host,
      pageFormat: g.pageFormat,
      topic: g.topic,
      whyItWins: g.whyItWins,
      questionsWon: g.questionsWon,
      timesCited: g.timesCited,
      engines: g.engines,
      status: 'To brief',
    },
  });
});

if (!out.length) {
  out.push({
    json: {
      gapId: r.brand + ' | ' + r.runDate + ' | none',
      runDate: r.runDate, brand: r.brand, rank: 0,
      sourceUrl: '', sourceHost: '', pageFormat: '', topic: 'No external citations this run',
      whyItWins: '', questionsWon: 0, timesCited: 0, engines: '', status: 'No action',
    },
  });
}

return out;
